// Do not edit this file. The hiring task is in registry.go.
package loan_test

import (
	"errors"
	"testing"

	"github.com/Hiring-Test-Blockchain/Test-Blockchain/loan"
)

const (
	owner    = "0xowner"
	platform = "0xplatform"
	borrower = "0xborrower"
	stranger = "0xstranger"
)

func newRegistry(t *testing.T) *loan.Registry {
	t.Helper()
	reg, err := loan.New(owner, platform)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	return reg
}

func disburse(t *testing.T, reg *loan.Registry, amountCents uint64) {
	t.Helper()
	if _, err := reg.CreateLoan(platform, "loan-pay", borrower, amountCents, 1299, 12, 900); err != nil {
		t.Fatalf("CreateLoan: %v", err)
	}
	if err := reg.ApproveLoan(platform, 1); err != nil {
		t.Fatalf("ApproveLoan: %v", err)
	}
	if err := reg.DisburseLoan(platform, 1); err != nil {
		t.Fatalf("DisburseLoan: %v", err)
	}
}

func TestCreateLoan(t *testing.T) {
	reg := newRegistry(t)
	id, err := reg.CreateLoan(platform, "loan-uuid-1", borrower, 100000, 1299, 12, 8900)
	if err != nil {
		t.Fatalf("CreateLoan: %v", err)
	}
	if id != 1 {
		t.Fatalf("loan id = %d, want 1", id)
	}
	stored, err := reg.GetLoan(1)
	if err != nil {
		t.Fatalf("GetLoan: %v", err)
	}
	if stored.Borrower != borrower || stored.Status != loan.StatusPending {
		t.Fatalf("stored = %+v", stored)
	}
	if stored.AmountCents != 100000 || stored.InterestRateBps != 1299 || stored.TermMonths != 12 {
		t.Fatalf("stored terms = %+v", stored)
	}
}

func TestApproveAndDisburse(t *testing.T) {
	reg := newRegistry(t)
	if _, err := reg.CreateLoan(platform, "loan-uuid-2", borrower, 50000, 1299, 6, 8500); err != nil {
		t.Fatalf("CreateLoan: %v", err)
	}
	if err := reg.ApproveLoan(platform, 1); err != nil {
		t.Fatalf("ApproveLoan: %v", err)
	}
	if err := reg.DisburseLoan(platform, 1); err != nil {
		t.Fatalf("DisburseLoan: %v", err)
	}
	stored, err := reg.GetLoan(1)
	if err != nil {
		t.Fatalf("GetLoan: %v", err)
	}
	if stored.Status != loan.StatusDisbursed {
		t.Fatalf("status = %d, want disbursed", stored.Status)
	}
}

func TestNonPlatformCannotCreate(t *testing.T) {
	reg := newRegistry(t)
	_, err := reg.CreateLoan(borrower, "loan-uuid-3", borrower, 1000, 100, 1, 100)
	if !errors.Is(err, loan.ErrUnauthorized) {
		t.Fatalf("err = %v, want ErrUnauthorized", err)
	}
}

func TestRemainingOfReturnsOutstandingBalance(t *testing.T) {
	reg := newRegistry(t)
	disburse(t, reg, 10_000)
	got, err := reg.RemainingOf(1)
	if err != nil {
		t.Fatalf("RemainingOf: %v", err)
	}
	if got != 10_000 {
		t.Fatalf("remaining = %d, want 10000", got)
	}
}

func TestRemainingOfMissingLoan(t *testing.T) {
	reg := newRegistry(t)
	_, err := reg.RemainingOf(99)
	if !errors.Is(err, loan.ErrLoanNotFound) {
		t.Fatalf("err = %v, want ErrLoanNotFound", err)
	}
}

func TestRecordPaymentBorrowerReducesRemaining(t *testing.T) {
	reg := newRegistry(t)
	disburse(t, reg, 10_000)
	if err := reg.RecordPayment(borrower, 1, 4_000); err != nil {
		t.Fatalf("RecordPayment: %v", err)
	}
	want := loan.Payment{LoanID: 1, Payer: borrower, AmountCents: 4_000, RemainingCents: 6_000}
	if len(reg.Payments) != 1 || reg.Payments[0] != want {
		t.Fatalf("payments = %+v, want [%+v]", reg.Payments, want)
	}
	got, err := reg.RemainingOf(1)
	if err != nil {
		t.Fatalf("RemainingOf: %v", err)
	}
	if got != 6_000 {
		t.Fatalf("remaining = %d, want 6000", got)
	}
	stored, err := reg.GetLoan(1)
	if err != nil {
		t.Fatalf("GetLoan: %v", err)
	}
	if stored.Status != loan.StatusDisbursed {
		t.Fatalf("status = %d, want disbursed", stored.Status)
	}
}

func TestRecordPaymentPlatform(t *testing.T) {
	reg := newRegistry(t)
	disburse(t, reg, 10_000)
	if err := reg.RecordPayment(platform, 1, 1_000); err != nil {
		t.Fatalf("RecordPayment: %v", err)
	}
	got, err := reg.RemainingOf(1)
	if err != nil {
		t.Fatalf("RemainingOf: %v", err)
	}
	if got != 9_000 {
		t.Fatalf("remaining = %d, want 9000", got)
	}
}

func TestRecordPaymentFinalMarksRepaid(t *testing.T) {
	reg := newRegistry(t)
	disburse(t, reg, 10_000)
	if err := reg.RecordPayment(borrower, 1, 10_000); err != nil {
		t.Fatalf("RecordPayment: %v", err)
	}
	want := loan.Payment{LoanID: 1, Payer: borrower, AmountCents: 10_000, RemainingCents: 0}
	if len(reg.Payments) != 1 || reg.Payments[0] != want {
		t.Fatalf("payments = %+v, want [%+v]", reg.Payments, want)
	}
	stored, err := reg.GetLoan(1)
	if err != nil {
		t.Fatalf("GetLoan: %v", err)
	}
	if stored.Status != loan.StatusRepaid {
		t.Fatalf("status = %d, want repaid", stored.Status)
	}
}

func TestRecordPaymentRejectsStranger(t *testing.T) {
	reg := newRegistry(t)
	disburse(t, reg, 10_000)
	err := reg.RecordPayment(stranger, 1, 100)
	if !errors.Is(err, loan.ErrUnauthorized) {
		t.Fatalf("err = %v, want ErrUnauthorized", err)
	}
	if len(reg.Payments) != 0 {
		t.Fatalf("payments recorded on failure: %+v", reg.Payments)
	}
}

func TestRecordPaymentRejectsZeroAndOverpayment(t *testing.T) {
	reg := newRegistry(t)
	disburse(t, reg, 10_000)
	if err := reg.RecordPayment(borrower, 1, 0); !errors.Is(err, loan.ErrInvalidAmount) {
		t.Fatalf("zero payment err = %v, want ErrInvalidAmount", err)
	}
	if err := reg.RecordPayment(borrower, 1, 10_001); !errors.Is(err, loan.ErrInvalidAmount) {
		t.Fatalf("overpayment err = %v, want ErrInvalidAmount", err)
	}
	if len(reg.Payments) != 0 {
		t.Fatalf("payments recorded on failure: %+v", reg.Payments)
	}
}

func TestRecordPaymentRejectsBeforeDisbursal(t *testing.T) {
	reg := newRegistry(t)
	if _, err := reg.CreateLoan(platform, "loan-not-disbursed", borrower, 5_000, 1299, 6, 900); err != nil {
		t.Fatalf("CreateLoan: %v", err)
	}
	err := reg.RecordPayment(borrower, 1, 100)
	if !errors.Is(err, loan.ErrInvalidStatusTransition) {
		t.Fatalf("err = %v, want ErrInvalidStatusTransition", err)
	}
}

func TestMarkDefaultedDisbursed(t *testing.T) {
	reg := newRegistry(t)
	if _, err := reg.CreateLoan(platform, "loan-default-ok", borrower, 5_000, 1299, 6, 900); err != nil {
		t.Fatalf("CreateLoan: %v", err)
	}
	if err := reg.ApproveLoan(platform, 1); err != nil {
		t.Fatalf("ApproveLoan: %v", err)
	}
	if err := reg.DisburseLoan(platform, 1); err != nil {
		t.Fatalf("DisburseLoan: %v", err)
	}
	if err := reg.MarkDefaulted(platform, 1); err != nil {
		t.Fatalf("MarkDefaulted: %v", err)
	}
	stored, err := reg.GetLoan(1)
	if err != nil {
		t.Fatalf("GetLoan: %v", err)
	}
	if stored.Status != loan.StatusDefaulted {
		t.Fatalf("status = %d, want defaulted", stored.Status)
	}
}

func TestMarkDefaultedRejectsApproved(t *testing.T) {
	reg := newRegistry(t)
	if _, err := reg.CreateLoan(platform, "loan-default-approved", borrower, 5_000, 1299, 6, 900); err != nil {
		t.Fatalf("CreateLoan: %v", err)
	}
	if err := reg.ApproveLoan(platform, 1); err != nil {
		t.Fatalf("ApproveLoan: %v", err)
	}
	err := reg.MarkDefaulted(platform, 1)
	if !errors.Is(err, loan.ErrInvalidStatusTransition) {
		t.Fatalf("err = %v, want ErrInvalidStatusTransition", err)
	}
}
